import { cn } from "@/common/utils";

interface FormFieldProps {
  id: string;
  label: string;
  name: string;
  type?: "text" | "email" | "tel";
  required?: boolean;
  placeholder?: string;
  className?: string;
}

interface FormTextareaProps {
  id: string;
  label: string;
  name: string;
  rows?: number;
  required?: boolean;
  placeholder?: string;
  className?: string;
}

const INPUT_CLASSES =
  "w-full rounded-lg border border-border bg-white px-4 py-2.5 text-sm text-accent placeholder:text-muted-foreground/50 transition-colors focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20";

const LABEL_CLASSES = "mb-1.5 block text-sm font-medium text-accent";

/**
 * Reusable form input field with label.
 * Eliminates duplicated input + label markup in forms.
 */
export function FormField({
  id,
  label,
  name,
  type = "text",
  required = false,
  placeholder,
  className,
}: FormFieldProps) {
  return (
    <div className={cn(className)}>
      <label htmlFor={id} className={LABEL_CLASSES}>
        {label}
      </label>
      <input
        id={id}
        name={name}
        type={type}
        required={required}
        placeholder={placeholder}
        className={INPUT_CLASSES}
      />
    </div>
  );
}

/**
 * Reusable form textarea field with label.
 */
export function FormTextarea({
  id,
  label,
  name,
  rows = 5,
  required = false,
  placeholder,
  className,
}: FormTextareaProps) {
  return (
    <div className={cn(className)}>
      <label htmlFor={id} className={LABEL_CLASSES}>
        {label}
      </label>
      <textarea
        id={id}
        name={name}
        required={required}
        rows={rows}
        placeholder={placeholder}
        className={cn(INPUT_CLASSES, "resize-none")}
      />
    </div>
  );
}
